def total_cost(num_glasses):
    cost_per_glass = 5
    discount = 0.6
    total = 0
    for i in range(num_glasses):
        if (i + 1) % 2 == 0:
            total += cost_per_glass * discount
        else:
            total += cost_per_glass
    return total

